<script setup>
import {computed,ref,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {withBase} from 'vitepress'
import data from './education.json'
const props=defineProps({course:String,group:String})
const course=computed(()=>data.courses.find(c=>c.path===props.course&&c.path!=='ms-project/index'))
const group=computed(()=>course.value?.group||props.group||'ms')
const info=computed(()=>data.academy[group.value])
const courses=computed(()=>data.courses.filter(c=>c.group===group.value&&c.presentation))
const selected=ref('all')
const visible=computed(()=>courses.value.filter(c=>selected.value==='all'||c.path===selected.value))
const intro=computed(()=>data.courses.find(c=>c.path==='ms-project/index'))
const inquiry=(c)=>withBase('/contact.html?service='+encodeURIComponent(info.value.title)+(c?'&course='+encodeURIComponent(c.path):''))
const home=computed(()=>withBase(group.value==='ms'?'/ms-project/':'/pm-practice/'))
const previewImage=computed(()=>course.value?.sections.flatMap(s=>s.images).find(i=>i.src))
const nav=[['과정 소개','intro'],['실습 결과물','outputs'],['커리큘럼','curriculum'],['준비·운영','environment'],['FAQ','faq']]
async function revealHash(){await nextTick(); const el=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(el?.tagName==='DETAILS'){el.open=true;el.scrollIntoView()}}
watch(group,()=>{selected.value='all'})
watch(()=>props.course,()=>revealHash())
onMounted(()=>{revealHash();window.addEventListener('hashchange',revealHash)})
onUnmounted(()=>window.removeEventListener('hashchange',revealHash))
</script>
<template><div class="ai-academy education-academy" :class="'academy-'+group" :style="{'--course-accent':course?.presentation.accent||info.accent}">
<section class="aa-hero" :class="{'aa-detail-hero':course}"><div class="aa-wrap aa-detail-grid">
 <div><a v-if="course" class="aa-back" :href="home">← {{info.title}} 전체 과정</a><span class="aa-eyebrow">{{info.eyebrow}}</span><p class="aa-kicker">기업·공공기관 맞춤형 실무 교육</p><h1 id="page-title"><template v-if="course">{{course.title}}</template><template v-else><template v-for="(line,i) in info.headline" :key="line"><br v-if="i"><em v-if="i===info.headline.length-1">{{line}}</em><template v-else>{{line}}</template></template></template></h1><p class="aa-lead preserve-lines">{{course?.subtitle||info.lead}}</p><div class="aa-actions"><a class="aa-btn aa-primary" :href="inquiry(course)">{{course?'이 과정 교육 문의':'우리 조직 교육 문의'}} ↗</a><a class="aa-btn aa-ghost" :href="course?'#curriculum':'#courses'">{{course?'전체 커리큘럼':'3개 과정 살펴보기'}} ↓</a></div><div class="aa-tool-line">{{group==='ms'?'Microsoft Project · Excel · WBS · Critical Path':'계획 · 실행·통제 · 위험·이슈 · 협업'}}</div></div>
 <aside v-if="course" class="aa-course-brief"><span class="aa-eyebrow">{{course.presentation.level}}</span><h2>교육에서 직접<br>작성하고 검토합니다.</h2><ul><li v-for="o in course.presentation.outputs" :key="o">↗ {{o}}</li></ul><div class="aa-brief-format"><strong>{{course.days}}일 · {{course.hours}}시간</strong><span>표준 구성 · 기업 맞춤형 조정</span></div></aside>
 <div v-else class="academy-visual"><img :src="withBase(info.image)" :alt="info.imageAlt" width="1144" height="761" fetchpriority="high"><div class="academy-visual-note"><span>LEARN → PRACTICE → REVIEW</span><strong>{{group==='ms'?'직접 작성하는 공정표, 직접 운영하는 관리 체계.':'내 프로젝트에 적용하는 관리 계획과 점검 기준.'}}</strong></div></div>
</div><div v-if="!course" class="aa-hero-bottom aa-wrap"><span><b>03</b> 목적별 전문 과정</span><span><b>실습</b> 관리 산출물 작성</span><span><b>맞춤</b> 산업·직무·수준별 구성</span></div></section>
<nav v-if="course" class="aa-subnav" aria-label="과정 상세 목차"><div class="aa-wrap"><a v-for="[label,id] in nav" :key="id" :href="'#'+id">{{label}}</a><a class="aa-nav-inquiry" :href="inquiry(course)">교육 문의 ↗</a></div></nav>
<template v-if="!course">
 <section id="courses" class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">FIND YOUR COURSE</span><h2>지금 맡은 업무에 맞는<br>과정을 선택하십시오.</h2><p>교육 목적과 현재 경험을 기준으로 비교하실 수 있습니다.</p></div><div class="aa-filters" aria-label="교육 과정 선택"><button :aria-pressed="selected==='all'" @click="selected='all'">전체 과정</button><button v-for="c in courses" :key="c.path" :aria-pressed="selected===c.path" @click="selected=c.path">{{c.presentation.short}}</button></div><p class="aa-result-count" aria-live="polite">{{visible.length}}개 과정</p><div class="aa-course-grid"><a v-for="(c,i) in visible" :key="c.path" class="aa-course-card" :href="withBase('/'+c.path+'.html')" :style="{'--card-accent':c.presentation.accent}"><div class="aa-cover academy-cover"><span class="aa-cover-tag">{{c.presentation.level}}</span><div class="aa-cover-word">{{c.presentation.word}}<sup>0{{i+1}}</sup></div><div class="academy-cover-foot">{{c.presentation.outputs[0]}}</div></div><div class="aa-card-body"><div class="aa-card-meta"><span>{{c.days}}일 · {{c.hours}}시간</span><span>기업 맞춤형</span></div><h3>{{c.title}}</h3><p>{{c.subtitle}}</p><div class="aa-card-output"><small>실습 결과물</small><strong>{{c.presentation.outputs.slice(0,2).join(' · ')}}</strong></div><div class="aa-card-foot"><span>{{c.sections.length}}개 상세 주제</span><strong>과정 자세히 ↗</strong></div></div></a></div></section>
 <section class="aa-section aa-soft"><div class="aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">COURSE GUIDE</span><h2>대상과 결과물로 비교하는<br>{{info.title}} 로드맵.</h2></div><div class="aa-comparison" tabindex="0" aria-label="과정 비교표, 작은 화면에서는 가로 스크롤"><table><thead><tr><th>추천 대상·업무</th><th>과정·수준</th><th>표준 시간</th><th>주요 결과물</th></tr></thead><tbody><tr v-for="c in courses" :key="c.path"><td>{{c.presentation.audience[0]}}</td><td><a :href="withBase('/'+c.path+'.html')">{{c.title}} ↗</a><small>{{c.presentation.level}}</small></td><td>{{c.days}}일<br>{{c.hours}}시간</td><td>{{c.presentation.outputs.join(' · ')}}</td></tr></tbody></table></div></div></section>
 <section id="outputs" class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">LEARN BY DOING</span><h2>배운 내용은,<br>실제 관리 자료로.</h2><p>{{info.case}}</p></div><div class="aa-value-grid"><article v-for="c in courses" :key="c.path"><span>{{c.presentation.short}}</span><h3>{{c.presentation.outputs[0]}}</h3><p>{{c.presentation.needs[0]}}</p><div class="aa-value-bottom">{{c.presentation.outputs.slice(1).join(' · ')}}</div></article></div></section>
 <section v-if="group==='ms'" id="curriculum" class="aa-section aa-soft"><div class="aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">EDUCATION OVERVIEW</span><h2>교육의 방향과<br>전체 내용을 확인하십시오.</h2></div><div class="aa-curriculum"><details v-for="s in intro.sections" :key="s.id" :id="s.id"><summary><strong>{{s.heading}}</strong><span class="aa-expand">+</span></summary><div class="aa-module-body"><div v-for="(block,i) in s.blocks" :key="i" class="academy-original-block"><p v-for="(line,j) in block" :key="j">{{line}}</p></div><div v-for="(table,i) in s.tables" :key="i" class="aa-comparison" tabindex="0" :aria-label="s.heading+' 표'"><table><thead><tr><th v-for="(cell,j) in table[0]" :key="j">{{cell}}</th></tr></thead><tbody><tr v-for="(row,j) in table.slice(1)" :key="j"><td v-for="(cell,k) in row" :key="k">{{cell}}</td></tr></tbody></table></div><div class="academy-original-media"><img v-for="im in s.images" :key="im.src" :src="withBase(im.src)" :alt="im.alt" loading="lazy"></div></div></details></div></div></section>
</template>
<template v-else>
 <section id="intro" class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">IS THIS YOUR WORK?</span><h2>이런 업무를 맡고 계신가요?</h2></div><div class="aa-needs"><article v-for="(n,i) in course.presentation.needs" :key="n"><span>0{{i+1}}</span><h3>{{n}}</h3></article></div><div class="aa-intro-grid"><div><h3>이런 분께 권합니다.</h3><ul class="aa-check-list"><li v-for="a in course.presentation.audience" :key="a">{{a}}</li></ul></div><div><h3>핵심 학습 목표</h3><ul class="aa-check-list"><li v-for="h in course.highlights" :key="h">{{h}}</li></ul></div></div></section>
 <section id="outputs" class="aa-section aa-dark"><div class="aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">YOUR PRACTICE PROJECT</span><h2>배우고, 작성하고,<br>검토하는 실습 결과물.</h2><p>{{info.case}}</p></div><div class="aa-output-grid"><article v-for="(o,i) in course.presentation.outputs" :key="o"><small>OUTPUT 0{{i+1}}</small><h3>{{o}}</h3><dl class="aa-output-example"><div><dt>입력</dt><dd>{{course.presentation.audience[0]}}의 업무 자료</dd></div><div><dt>작성</dt><dd>{{course.highlights[i%course.highlights.length]}}</dd></div><div><dt>검토</dt><dd>교육 사례의 요구사항과 작성 결과 비교</dd></div></dl></article></div><img v-if="previewImage" class="academy-preview" :src="withBase(previewImage.src)" :alt="previewImage.alt" loading="lazy"></div></section>
 <section id="curriculum" class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">CURRICULUM</span><h2>전체 교육 내용과<br>실습 커리큘럼.</h2><p>{{course.days}}일 · {{course.hours}}시간 표준 구성. 주제를 펼쳐 세부 내용·표·화면을 확인하십시오.</p></div><div class="aa-curriculum"><details v-for="(s,i) in course.sections" :key="s.id" :id="s.id" :open="i===0"><summary><span class="aa-module-no">PART {{String(i+1).padStart(2,'0')}}</span><strong>{{s.heading}}</strong><span class="aa-expand">+</span></summary><div class="aa-module-body"><div v-for="(block,j) in s.blocks" :key="j" class="academy-original-block"><p v-for="(line,k) in block" :key="k">{{line}}</p></div><div v-for="(table,j) in s.tables" :key="j" class="aa-comparison" tabindex="0" :aria-label="s.heading+' 표'"><table><thead><tr><th v-for="(cell,k) in table[0]" :key="k">{{cell}}</th></tr></thead><tbody><tr v-for="(row,k) in table.slice(1)" :key="k"><td v-for="(cell,l) in row" :key="l">{{cell}}</td></tr></tbody></table></div><div class="academy-original-media"><img v-for="im in s.images" :key="im.src" :src="withBase(im.src)" :alt="im.alt" loading="lazy"></div></div></details></div><p v-if="course.time_note" class="aa-note">전체 과정을 {{course.days}}일 {{course.hours}}시간으로 구성합니다. 세부 모듈 시간과 일차별 배분에는 차이가 있어, 실제 시간표는 선택 주제와 실습 범위를 반영하여 교육 전에 조정합니다.</p></section>
 <section id="environment" class="aa-section aa-soft"><div class="aa-wrap aa-environment-grid"><div class="aa-section-head"><span class="aa-eyebrow">BEFORE YOU START</span><h2>실습 준비와<br>교육 운영 안내.</h2></div><div><article><h3>참여 전 필요한 경험</h3><p>{{course.presentation.prerequisite}}</p></article><article><h3>준비할 도구·자료</h3><p>{{group==='ms'?'Microsoft Project와 Excel의 버전·라이선스·설치 상태, 조직의 공정표와 보고 양식을 확인합니다.':'교육 사례와 실습 자료, 필요한 문서·분석 도구를 교육 전에 확인합니다.'}} 회사 자료는 사용 권한과 보안 조건을 확인하여 준비합니다.</p></article><article><h3>교육 운영</h3><p>{{course.days}}일 · {{course.hours}}시간 표준 구성. 교육 대상·수준과 선택 실습에 맞춰 실제 시간표를 협의합니다. 개강일과 수강료는 문의 시 안내합니다.</p></article><article v-if="group==='ms'"><h3>제품과 협업 환경</h3><p>기존 자료에 포함된 Project Online 주제는 과거 구성의 이해와 협업 환경 전환 관점으로 다룹니다. 실제 실습은 사용 가능한 제품과 라이선스를 확인하여 구성합니다.</p></article><article v-if="course.path==='pm-practice/project-management'"><h3>교육 이력 안내</h3><p>영문 수료증은 교육 이력 증빙입니다. PDU는 PMI의 자격 유지 규정에 따라 개별 신청합니다.</p></article></div></div></section>
</template>
<section class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">BUILT FOR YOUR TEAM</span><h2>우리 조직에 맞춰,<br>이렇게 준비합니다.</h2></div><div class="aa-process"><article v-for="(p,i) in data.academy.process" :key="p.title"><span>0{{i+1}}</span><h3>{{p.title}}</h3><p>{{p.text}}</p></article></div></section>
<section class="aa-instructor aa-soft"><div class="aa-wrap aa-instructor-grid"><img :src="withBase('/images/nam-woongchan.webp')" alt="피엠오피스 남웅찬 대표" width="740" height="522" loading="lazy"><div><span class="aa-eyebrow">PM, IN PRACTICE</span><h2>프로젝트의 업무 맥락을 아는<br>실무 중심 교육.</h2><p>기업 공정 관리와 국가연구개발 사업 관리의 담당 업무에 맞춰 교육 사례와 실습을 구성합니다.</p><strong>남웅찬 · 피엠오피스 대표</strong><div class="aa-instructor-tags"><span>PMP</span><span>Microsoft Project Specialist</span></div><a :href="withBase('/about.html')">강사·피엠오피스 소개 보기 ↗</a></div></div></section>
<section id="faq" class="aa-section aa-wrap"><div class="aa-section-head"><span class="aa-eyebrow">FAQ</span><h2>교육 전에 궁금한 점.</h2></div><div class="aa-faq"><details v-for="f in data.academy.faq" :key="f.q"><summary>{{f.q}}<span>+</span></summary><p>{{f.a}}</p></details></div></section>
<section class="aa-cta"><div class="aa-wrap"><span class="aa-eyebrow">LET'S BUILD YOUR CURRICULUM</span><h2>담당 업무와 필요한 실습을<br>알려주십시오.</h2><p>교육 대상·현재 수준·사용 환경·희망 일정을 기준으로<br>과정과 실습 범위를 구체적으로 제안하겠습니다.</p><div class="aa-actions"><a class="aa-btn aa-primary" :href="inquiry(course)">{{info.title}} 문의 ↗</a><a class="aa-contact" href="mailto:nam@pmoffice.co.kr">nam@pmoffice.co.kr</a></div></div></section>
<div v-if="course" class="aa-mobile-inquiry"><span>{{course.presentation.short}} · {{course.hours}}시간</span><a :href="inquiry(course)">교육 문의 ↗</a></div>
</div></template>
